import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../models/check_in.dart';
import 'dialog_frame.dart';

/// Shows the ready-to-paste prompt for a check-in. The audience variant is in
/// the title, so switching to a performance review is visible in the prompt
/// itself. The prompt block is generated by the service; the client only
/// displays and copies it.
Future<void> showPromptDialog(
  BuildContext context, {
  required CheckInPrompt prompt,
}) {
  return showDialog<void>(
    context: context,
    builder: (context) => _PromptDialog(prompt: prompt),
  );
}

class _PromptDialog extends StatelessWidget {
  const _PromptDialog({required this.prompt});

  final CheckInPrompt prompt;

  Future<void> _copy(BuildContext context) async {
    await Clipboard.setData(ClipboardData(text: prompt.prompt));
    if (!context.mounted) return;
    Navigator.of(context).pop();
    ScaffoldMessenger.of(
      context,
    ).showSnackBar(const SnackBar(content: Text('Prompt copied to clipboard')));
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;
    return DialogFrame(
      title: 'Copy prompt · ${prompt.variant.label}',
      subtitle: 'Prompt ${prompt.promptVersion} · prepended to summary.md',
      icon: Icons.copy_all_outlined,
      maxWidth: 760,
      content: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Text(
            'The audience selects the prompt variant. Your summary and the '
            'recorded data never change.',
            style: theme.textTheme.bodySmall?.copyWith(
              color: scheme.onSurfaceVariant,
            ),
          ),
          const SizedBox(height: 12),
          Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: scheme.surfaceContainerHighest.withValues(alpha: 0.4),
              borderRadius: BorderRadius.circular(8),
            ),
            child: SelectableText(
              prompt.prompt,
              style: theme.textTheme.bodySmall?.copyWith(
                fontFamily: 'monospace',
                height: 1.5,
              ),
            ),
          ),
        ],
      ),
      actions: Row(
        mainAxisAlignment: MainAxisAlignment.end,
        children: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(),
            child: const Text('Close'),
          ),
          const SizedBox(width: 6),
          FilledButton.icon(
            onPressed: () => _copy(context),
            icon: const Icon(Icons.copy_all, size: 16),
            label: const Text('Copy'),
          ),
        ],
      ),
    );
  }
}
